import{_ as h,C as l,o,c as s,E as r,a1 as e,b as n,w as d,a as E,a2 as i}from"./chunks/framework.NjEjlYNI.js";const m=JSON.parse('{"title":"测试用例设计","description":"测试用例设计方法 — 用例 8 要素、等价类划分、边界值分析、因果图/判定表、场景法、错误推测法、正交试验法，每个方法附真实例子","frontmatter":{"title":"测试用例设计","description":"测试用例设计方法 — 用例 8 要素、等价类划分、边界值分析、因果图/判定表、场景法、错误推测法、正交试验法，每个方法附真实例子","difficulty":"beginner","frequency":"high"},"headers":[],"relativePath":"testing/test-case-design.md","filePath":"testing/test-case-design.md"}'),q={name:"testing/test-case-design.md"};function B(c,t,b,A,g,p){const u=l("DifficultyBadge"),a=l("Mermaid");return o(),s("div",null,[r(u,{level:"beginner"}),t[2]||(t[2]=e('<h1 id="测试用例设计" tabindex="-1">测试用例设计 <a class="header-anchor" href="#测试用例设计" aria-label="Permalink to &quot;测试用例设计&quot;">​</a></h1><h2 id="一句话解释" tabindex="-1">一句话解释 <a class="header-anchor" href="#一句话解释" aria-label="Permalink to &quot;一句话解释&quot;">​</a></h2><p>测试用例设计就是用<strong>最少数量、最高效率的用例，覆盖最多可能出错的分支</strong>。核心思想是：输入组合是无限的、测不完，所以必须用科学方法把&quot;无限输入&quot;压缩成&quot;有限高价值用例&quot;——<strong>用例设计能力，是区分测试员和&quot;点工&quot;的分水岭</strong>。</p><h2 id="核心流程-一个用例怎么诞生" tabindex="-1">核心流程：一个用例怎么诞生 <a class="header-anchor" href="#核心流程-一个用例怎么诞生" aria-label="Permalink to &quot;核心流程：一个用例怎么诞生&quot;">​</a></h2>',4)),(o(),n(i,null,{default:d(()=>[r(a,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E9%9C%80%E6%B1%82%E6%96%87%E6%A1%A3%20PRD%22%5D%20--%3E%20B%5B%22%E6%8B%86%E8%A7%A3%E5%8A%9F%E8%83%BD%E7%82%B9%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E9%80%89%E6%8B%A9%E8%AE%BE%E8%AE%A1%E6%96%B9%E6%B3%95%3Cbr%2F%3E%E7%AD%89%E4%BB%B7%E7%B1%BB%20%E8%BE%B9%E7%95%8C%E5%80%BC%20%E5%9C%BA%E6%99%AF%E6%B3%95%20%E5%88%A4%E5%AE%9A%E8%A1%A8%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E7%BC%96%E5%86%99%E6%B5%8B%E8%AF%95%E7%94%A8%E4%BE%8B%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E7%94%A8%E4%BE%8B%E8%AF%84%E5%AE%A1%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E6%89%A7%E8%A1%8C%E5%B9%B6%E8%B7%9F%E8%B8%AA%E7%BC%BA%E9%99%B7%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E7%BB%B4%E6%8A%A4%E4%B8%8E%E5%9B%9E%E5%BD%92%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[E(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=e('<h2 id="深入理解" tabindex="-1">深入理解 <a class="header-anchor" href="#深入理解" aria-label="Permalink to &quot;深入理解&quot;">​</a></h2><h3 id="_1-测试用例的-8-要素" tabindex="-1">1. 测试用例的 8 要素 <a class="header-anchor" href="#_1-测试用例的-8-要素" aria-label="Permalink to &quot;1. 测试用例的 8 要素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>说明</th><th>示例（登录功能）</th></tr></thead><tbody><tr><td>用例编号</td><td>唯一标识，<code>TC_模块_序号</code></td><td><code>TC_Login_002</code></td></tr><tr><td>用例标题</td><td>一句话说清&quot;测什么&quot;</td><td>验证空密码点击登录给出提示</td></tr><tr><td>前置条件</td><td>测试前必须满足的状态</td><td>打开登录页</td></tr><tr><td>测试步骤</td><td>一步步的操作指令</td><td>输入用户名 → 密码留空 → 点登录</td></tr><tr><td>测试数据</td><td>输入的数据</td><td>用户名 <code>abc123</code>，密码为空</td></tr><tr><td>预期结果</td><td>期望软件的表现</td><td>提示&quot;请输入密码&quot;，不跳转</td></tr><tr><td>实际结果</td><td>执行后真实表现</td><td>（执行时填写）</td></tr><tr><td>优先级</td><td>P0-P3，决定执行顺序</td><td>P1</td></tr></tbody></table><p><strong>一条完整用例长这样：</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>用例编号</td><td><code>TC_Login_002</code></td></tr><tr><td>所属模块</td><td>登录</td></tr><tr><td>用例标题</td><td>验证空密码点击登录给出提示</td></tr><tr><td>优先级</td><td>P1</td></tr><tr><td>前置条件</td><td>打开登录页</td></tr><tr><td>测试数据</td><td>用户名 <code>abc123</code>，密码留空</td></tr><tr><td>测试步骤</td><td>1. 输入用户名 <code>abc123</code>；2. 密码留空；3. 点击&quot;登录&quot;按钮</td></tr><tr><td>预期结果</td><td>页面提示&quot;请输入密码&quot;，不跳转、不请求接口</td></tr><tr><td>实际结果</td><td>待填写</td></tr><tr><td>执行状态</td><td>待执行</td></tr></tbody></table><h3 id="_2-等价类划分法" tabindex="-1">2. 等价类划分法 <a class="header-anchor" href="#_2-等价类划分法" aria-label="Permalink to &quot;2. 等价类划分法&quot;">​</a></h3><p><strong>原理</strong>：把无穷无尽的输入，按&quot;是否产生同类结果&quot;分成若干等价类，每类只测一个代表值。<strong>有效等价类</strong>（合理输入）和<strong>无效等价类</strong>（不合理输入）都要测——无效类最能抓 bug。</p><p><strong>真实例子：登录用户名输入框</strong></p><blockquote><p>需求：用户名必填，要求 <strong>6-20 位字母或数字</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类别</th><th>等价类</th><th>测试数据</th><th>预期结果</th></tr></thead><tbody><tr><td>有效</td><td>6-20 位纯字母</td><td><code>abcdef</code></td><td>通过</td></tr><tr><td>有效</td><td>6-20 位纯数字</td><td><code>123456</code></td><td>通过</td></tr><tr><td>有效</td><td>字母数字混合</td><td><code>abc123</code></td><td>通过</td></tr><tr><td>无效</td><td>空</td><td>（不输入）</td><td>提示&quot;用户名不能为空&quot;</td></tr><tr><td>无效</td><td>少于 6 位</td><td><code>abc12</code></td><td>提示&quot;至少 6 位&quot;</td></tr><tr><td>无效</td><td>多于 20 位</td><td>21 个字符</td><td>提示&quot;最多 20 位&quot;</td></tr><tr><td>无效</td><td>含特殊字符</td><td><code>abc#123</code></td><td>提示&quot;仅支持字母数字&quot;</td></tr><tr><td>无效</td><td>含中文</td><td><code>测试abc</code></td><td>提示&quot;仅支持字母数字&quot;</td></tr></tbody></table><blockquote><p><strong>实战贴士</strong>：每个无效等价类都要单独一条用例。如果把&quot;空、小于6位、含特殊字符&quot;合在一起测，报错了你不知道是哪个条件触发的。</p></blockquote><h3 id="_3-边界值分析法" tabindex="-1">3. 边界值分析法 <a class="header-anchor" href="#_3-边界值分析法" aria-label="Permalink to &quot;3. 边界值分析法&quot;">​</a></h3><p><strong>原理</strong>：大量缺陷都发生在<strong>边界附近</strong>（<code>==</code> 写成了 <code>&lt;</code>、长度判断少一位）。边界值法是对等价类的补充：测上边界、下边界、以及紧挨边界的值（<code>边界±1</code>）。<strong>等价类管&quot;桶&quot;，边界值管&quot;桶边&quot;</strong>，两者几乎总是一起用。</p><p><strong>真实例子：注册表单年龄校验</strong></p><blockquote><p>需求：年龄必须在 <strong>18-60 周岁</strong>之间（含 18 和 60）。</p></blockquote><table tabindex="0"><thead><tr><th>测试点</th><th>测试数据</th><th>预期结果</th></tr></thead><tbody><tr><td>下边界</td><td>18</td><td>通过</td></tr><tr><td>下边界 - 1</td><td>17</td><td>拒绝，提示&quot;未满 18 岁&quot;</td></tr><tr><td>上边界</td><td>60</td><td>通过</td></tr><tr><td>上边界 + 1</td><td>61</td><td>拒绝，提示&quot;超过 60 岁&quot;</td></tr><tr><td>边界内代表值</td><td>35</td><td>通过</td></tr><tr><td>非数字</td><td><code>abc</code></td><td>拒绝，提示&quot;请输入数字&quot;</td></tr></tbody></table><blockquote><p><strong>记忆锚点</strong>：边界值法只测 4 个点（上界、上界+1、下界、下界-1）加 1 个代表值，就能覆盖这 6 条用例。这就是&quot;最少用例覆盖最多分支&quot;的体现。</p></blockquote><h3 id="_4-因果图-判定表法" tabindex="-1">4. 因果图 / 判定表法 <a class="header-anchor" href="#_4-因果图-判定表法" aria-label="Permalink to &quot;4. 因果图 / 判定表法&quot;">​</a></h3><p><strong>原理</strong>：当功能由<strong>多个条件的组合</strong>决定动作时，用判定表列出&quot;条件桩 × 动作桩&quot;，一个组合一行，保证组合全覆盖、不漏测。因果图是画法，判定表是落地的表。</p><p><strong>真实例子：购物车结算</strong></p><blockquote><p>三个条件：C1 是否已登录、C2 商品是否有库存、C3 余额是否充足。 四个动作：A1 支付成功、A2 跳转登录页、A3 提示库存不足、A4 提示余额不足。</p></blockquote><table tabindex="0"><thead><tr><th>C1 已登录</th><th>C2 有库存</th><th>C3 余额充足</th><th>动作</th></tr></thead><tbody><tr><td>否</td><td>—</td><td>—</td><td>A2 跳转登录页</td></tr><tr><td>是</td><td>否</td><td>—</td><td>A3 提示库存不足</td></tr><tr><td>是</td><td>是</td><td>否</td><td>A4 提示余额不足</td></tr><tr><td>是</td><td>是</td><td>是</td><td>A1 支付成功</td></tr></tbody></table><blockquote><p><strong>实战贴士</strong>：凡是有&quot;权限组合、优惠规则、多条件校验&quot;的地方（如&quot;登录 + VIP + 满减&quot;），都是判定表的用武之地。注意条件之间可能互相依赖（如&quot;没登录&quot;时其余条件无意义），用 <code>—</code> 表示不参与判断。</p></blockquote><h3 id="_5-场景法" tabindex="-1">5. 场景法 <a class="header-anchor" href="#_5-场景法" aria-label="Permalink to &quot;5. 场景法&quot;">​</a></h3><p><strong>原理</strong>：很多缺陷不在&quot;单个功能&quot;，而在<strong>业务流的串联</strong>。场景法把用户的操作画成&quot;基本流 + 备选流 + 异常流&quot;，沿着用户的路径走一遍。</p><p><strong>真实例子：完整购物流程</strong></p>',26)),(o(),n(i,null,{default:d(()=>[r(a,{id:"mermaid-580",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20S%5B%22%E5%9F%BA%E6%9C%AC%E6%B5%81%3Cbr%2F%3E%E7%99%BB%E5%BD%95%20%E2%86%92%20%E6%90%9C%E7%B4%A2%E5%95%86%E5%93%81%20%E2%86%92%20%E5%8A%A0%E5%85%A5%E8%B4%AD%E7%89%A9%E8%BD%A6%20%E2%86%92%20%E7%BB%93%E7%AE%97%20%E2%86%92%20%E6%94%AF%E4%BB%98%20%E2%86%92%20%E4%B8%8B%E5%8D%95%E6%88%90%E5%8A%9F%22%5D%0A%20%20%20%20S%20--%3E%20B1%5B%22%E5%A4%87%E9%80%89%E6%B5%81%3Cbr%2F%3E%E5%BA%93%E5%AD%98%E4%B8%8D%E8%B6%B3%EF%BC%9A%E6%8F%90%E7%A4%BA%E5%90%8E%E8%BF%94%E5%9B%9E%E8%B4%AD%E7%89%A9%E8%BD%A6%22%5D%0A%20%20%20%20S%20--%3E%20B2%5B%22%E5%A4%87%E9%80%89%E6%B5%81%3Cbr%2F%3E%E4%BC%98%E6%83%A0%E5%88%B8%E4%B8%8D%E6%BB%A1%E8%B6%B3%E9%97%A8%E6%A7%9B%EF%BC%9A%E6%8F%90%E7%A4%BA%E5%90%8E%E5%8F%AF%E4%B8%8D%E4%BD%BF%E7%94%A8%22%5D%0A%20%20%20%20S%20--%3E%20B3%5B%22%E5%BC%82%E5%B8%B8%E6%B5%81%3Cbr%2F%3E%E6%94%AF%E4%BB%98%E8%B6%85%E6%97%B6%EF%BC%9A%E8%AE%A2%E5%8D%95%E7%BD%AE%E4%B8%BA%E5%BE%85%E6%94%AF%E4%BB%98%EF%BC%8C%E5%8F%AF%E9%87%8D%E8%AF%95%22%5D%0A%20%20%20%20S%20--%3E%20B4%5B%22%E5%BC%82%E5%B8%B8%E6%B5%81%3Cbr%2F%3E%E6%96%AD%E7%BD%91%E9%87%8D%E8%BF%9E%EF%BC%9A%E7%99%BB%E5%BD%95%E6%80%81%E5%A4%B1%E6%95%88%EF%BC%8C%E6%8F%90%E7%A4%BA%E9%87%8D%E6%96%B0%E7%99%BB%E5%BD%95%22%5D%0A"})]),fallback:d(()=>[...t[1]||(t[1]=[E(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=e('<table tabindex="0"><thead><tr><th>流类型</th><th>例子</th><th>关注点</th></tr></thead><tbody><tr><td>基本流</td><td>一路顺畅买到东西</td><td>主路径能不能通</td></tr><tr><td>备选流</td><td>库存不足、优惠券不满足、地址缺失</td><td>每一步的&quot;否则&quot;分支</td></tr><tr><td>异常流</td><td>支付超时、断网、接口 500</td><td>意外中断后数据/状态是否一致</td></tr></tbody></table><blockquote><p><strong>实战贴士</strong>：场景法测的是<strong>状态的迁移</strong>（比如&quot;待支付&quot;能不能回到&quot;已支付&quot;、&quot;超时&quot;后订单会不会凭空消失）。前端转测试的你会写状态机，这正好是你的强项。</p></blockquote><h3 id="_6-错误推测法" tabindex="-1">6. 错误推测法 <a class="header-anchor" href="#_6-错误推测法" aria-label="Permalink to &quot;6. 错误推测法&quot;">​</a></h3><p><strong>原理</strong>：不靠设计，靠<strong>经验 + 直觉</strong>猜测哪些地方最容易出错，直接补用例。它是前面所有方法之外的&quot;第六感&quot;，测试老手的价值就在这里。</p><p><strong>通用错误清单（高频命中区）：</strong></p><table tabindex="0"><thead><tr><th>类别</th><th>易错场景</th></tr></thead><tbody><tr><td>空值</td><td>空字符串、空数组、空对象、null</td></tr><tr><td>极限</td><td>超长文本、超大数字、0、负数、最小/最大单位</td></tr><tr><td>特殊字符</td><td><code>&#39;</code> <code>&quot;</code> <code>\\</code> <code>%</code> <code>#</code>、Emoji、SQL 注入串 <code>&#39; OR 1=1--</code></td></tr><tr><td>重复操作</td><td>双击提交、快速连点、重复下单</td></tr><tr><td>时间边界</td><td>0 点整、月末、最后一天、跨年</td></tr><tr><td>网络异常</td><td>断网重连、弱网、超时、接口报 500</td></tr><tr><td>权限</td><td>未登录访问、越权访问他人数据、过期 token</td></tr><tr><td>缓存/数据</td><td>刷新后数据丢失、旧缓存不更新、重复数据</td></tr></tbody></table><blockquote><p><strong>前端转测特别提醒</strong>：你自己踩过的坑就是最好的用例来源——输入框防抖没做导致重复提交、图片懒加载失败、<code>overflow</code> 溢出被截断、缓存穿透……这些&quot;前端才知道的坑&quot;，写进用例就是你的差异化竞争力。</p></blockquote><h3 id="_7-正交试验法" tabindex="-1">7. 正交试验法 <a class="header-anchor" href="#_7-正交试验法" aria-label="Permalink to &quot;7. 正交试验法&quot;">​</a></h3><p><strong>原理</strong>：当有<strong>多个因子、每个因子有多个水平</strong>时，全组合是&quot;指数爆炸&quot;（如 2³=8、3×2×2=12），根本测不完。正交试验法用<strong>正交表</strong>挑出最有代表性的组合，用少量用例覆盖绝大多数组合情况。</p><p><strong>真实例子：支付兼容性测试</strong></p><blockquote><p>3 个因子 × 2 个水平：浏览器（Chrome / Firefox）× 支付方式（微信 / 支付宝）× 网络（4G / WiFi）。 全组合 = 2×2×2 = <strong>8 条</strong>；用 L4 正交表只需 <strong>4 条</strong>：</p></blockquote><table tabindex="0"><thead><tr><th>用例</th><th>浏览器</th><th>支付方式</th><th>网络</th></tr></thead><tbody><tr><td>1</td><td>Chrome</td><td>微信</td><td>4G</td></tr><tr><td>2</td><td>Chrome</td><td>支付宝</td><td>WiFi</td></tr><tr><td>3</td><td>Firefox</td><td>微信</td><td>WiFi</td></tr><tr><td>4</td><td>Firefox</td><td>支付宝</td><td>4G</td></tr></tbody></table><blockquote><p>这 4 个组合里，每个因子的每个水平都出现了 2 次，且两两因子间的组合（浏览器×支付方式、浏览器×网络、支付方式×网络）都被覆盖到——这就是&quot;正交&quot;的含义。</p></blockquote><h3 id="_8-方法选型总结" tabindex="-1">8. 方法选型总结 <a class="header-anchor" href="#_8-方法选型总结" aria-label="Permalink to &quot;8. 方法选型总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>擅长发现</th><th>适用场景</th><th>一句话记忆</th></tr></thead><tbody><tr><td>等价类划分</td><td>同类输入处理错误</td><td>所有输入框、选项</td><td>把无限输入分进几个桶</td></tr><tr><td>边界值分析</td><td>边界附近逻辑错误</td><td>有范围的数字/长度/日期</td><td>边界值最易踩坑</td></tr><tr><td>因果图/判定表</td><td>多条件组合漏逻辑</td><td>权限、优惠规则、多条件校验</td><td>条件 → 动作查表</td></tr><tr><td>场景法</td><td>业务流程串联缺陷</td><td>购物、开户、审批等多步流程</td><td>沿着用户走一遍</td></tr><tr><td>错误推测法</td><td>经验性、偶发性缺陷</td><td>补漏、做真机/异常测试</td><td>老测试的第六感</td></tr><tr><td>正交试验法</td><td>组合爆炸</td><td>兼容性、多因子多水平配置</td><td>最少组合覆盖最大范围</td></tr></tbody></table><h2 id="面试问法" tabindex="-1">面试问法 <a class="header-anchor" href="#面试问法" aria-label="Permalink to &quot;面试问法&quot;">​</a></h2><ul><li><p>🔥 <strong>有哪些测试用例设计方法？</strong></p><ul><li>等价类划分、边界值分析、因果图/判定表、场景法、错误推测法、正交试验法</li><li>关键话术：前两个必答（基础），再补一个场景法/判定表（有实战感）</li></ul></li><li><p>🔥 <strong>等价类划分和边界值怎么结合用？</strong></p><ul><li>等价类把输入分成有效/无效两类，边界值专门测分类的&quot;边界 ±1&quot;</li><li>举例：年龄 18-60，等价类选代表值 35，边界值测 17/18/60/61</li></ul></li><li><p>🔥 <strong>现场写一个&quot;登录功能&quot;的测试用例设计思路？</strong></p><ul><li>等价类：正确账号密码 / 错密码 / 空用户名 / 空密码 / 不存在账号</li><li>边界值：密码长度上/下边界；场景法：登录成功跳转、登录失败提示、连续失败锁定</li><li>异常：弱网、接口 500、回车提交、重复点击</li></ul></li><li><p>⭐ <strong>场景法和等价类的区别？</strong></p><ul><li>等价类测&quot;单个输入&quot;，场景法测&quot;流程串联&quot;；场景法关注状态迁移，等价类关注取值</li></ul></li><li><p>⭐ <strong>什么是判定表？什么时候用？</strong></p><ul><li>条件桩 × 动作桩的规则表；当功能由多条件组合决定动作时用（权限、优惠规则）</li></ul></li><li><p>⭐ <strong>正交试验法解决什么问题？</strong></p><ul><li>多因子多水平组合爆炸；用正交表选代表性组合，用最少用例覆盖最大组合范围</li></ul></li></ul><h2 id="💡-ai-辅助学习" tabindex="-1">💡 AI 辅助学习 <a class="header-anchor" href="#💡-ai-辅助学习" aria-label="Permalink to &quot;💡 AI 辅助学习&quot;">​</a></h2><blockquote><p>用这个 Prompt 练测试思维： &quot;你是一位资深测试工程师，现在当我的导师。题目：&#39;一个注册表单，包含用户名、邮箱、年龄（18-60）、密码、确认密码&#39;。第一步，先让我自己说出：会用哪些用例设计方法、能想到哪些边界条件和组合。第二步，你帮我补全我遗漏的边界值、无效等价类和判定表条件组合，并指出我的方法缺口。第三步，把&#39;判定表&#39;和&#39;场景法&#39;用这个注册场景给我演示一遍完整用例。要求全程中文，点评要具体到&#39;这条为什么该测&#39;。&quot;</p></blockquote><h3 id="🤖-ai-输出成果-基于上面这个-prompt-生成" tabindex="-1">🤖 AI 输出成果（基于上面这个 Prompt 生成） <a class="header-anchor" href="#🤖-ai-输出成果-基于上面这个-prompt-生成" aria-label="Permalink to &quot;🤖 AI 输出成果（基于上面这个 Prompt 生成）&quot;">​</a></h3><blockquote><p>下面三件套就是 AI 基于上面这个 Prompt 实际生成的测试学习资源，点击后在新窗口打开、可离线使用：</p></blockquote><ul><li>📄 <a href="../qa-cheatsheet.pdf" target="_blank" rel="noopener">测试岗位 A4 速查 PDF</a> — 用例设计方法一页速记</li><li>🎬 <a href="../qa-demo.html" target="_blank" rel="noopener">测试交互式演示</a> — 跟着演示走一遍用例设计全流程</li><li>📝 <a href="../qa-quiz.html" target="_blank" rel="noopener">测试 Mini Quiz</a> — 现场设计用例自测</li></ul><h2 id="关联知识" tabindex="-1">关联知识 <a class="header-anchor" href="#关联知识" aria-label="Permalink to &quot;关联知识&quot;">​</a></h2><ul><li><a href="./test-basics.html">软件测试基础</a> — 7 大原则中&quot;穷尽测试不可能&quot;的落地方法</li><li><a href="./defect-management.html">缺陷管理</a> — 用例执行后发现的 bug 如何管理</li><li><a href="./interface-testing.html">接口测试</a> — 接口用例也用等价类/边界值，方法互通</li><li><a href="./test-interview.html">转岗测试面试专题</a> — &quot;现场设计用例&quot;是转岗面试必考题</li></ul>',24))])}const f=h(q,[["render",B]]);export{m as __pageData,f as default};
